mapper.update:
merge into t_cx_stock_location_sort a USING (
select #{SpecifyMachine.stockLocation,jdbcType=VARCHAR} stock_location, #{SpecifyMachine.productSort,jdbcType=DECIMAL} product_sort, #{SpecifyMachine.createBy,jdbcType=VARCHAR} create_by, #{SpecifyMachine.createTime,jdbcType=DATE} create_time, #{SpecifyMachine.updateBy,jdbcType=VARCHAR} update_by, #{SpecifyMachine.updateTime,jdbcType=DATE} update_time, #{SpecifyMachine.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.stock_location = b.stock_location AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.product_sort = b.product_sort, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.stock_location, a.product_sort,a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_PUBLIC.NEXTVAL, b.stock_location, b.product_sort, b.create_by, sysdate, b.remark, '0')
